mapper.select:
select t.area,t.amount,t.fee_name feeName,t.detail_id detailId,t.start_time startTime,t.status_cd statusCd,
t.end_time endTime,t.community_id communityId,t.receipt_id receiptId,t.fee_id feeId,t.cycle,t.square_price squarePrice,
t.remark,d.name primeRate,fr.obj_id payerObjId,t.ft_name ftName,fr.receipt_code receiptCode,
t.print_count printCount,t.acct_amount acctAmount,
t.fee_month feeMonth,t.start_degree startDegree,t.end_degree endDegree,
t.start_degree preDegrees,t.end_degree curDegrees,
pfd.pay_order_id payOrderId,
t.pay_way payWay,t.deduction_amount deductionAmount,t.late_amount lateAmount
from fee_receipt_detail t
left join fee_receipt fr on t.receipt_id = fr.receipt_id and fr.status_cd = '0' and t.community_id = fr.community_id
left join t_dict d on t.pay_way = d.status_cd and d.table_name="pay_fee_detail" and  d.table_columns='prime_rate'
left join pay_fee_detail pfd on t.detail_id = pfd.detail_id and pfd.status_cd = '0'
where 1 =1

    and t.area= #{area}


    and t.amount= #{amount}


    and t.fee_name= #{feeName}


    and t.detail_id= #{detailId}


    and t.detail_id in

        #{item}



    and t.start_time= #{startTime}


    and t.status_cd= #{statusCd}


    and t.end_time= #{endTime}


    and t.community_id= #{communityId}


    and t.receipt_id= #{receiptId}


    and t.receipt_id in

        #{item}



    and t.fee_id= #{feeId}


    and t.cycle= #{cycle}


    order by t.fee_name, t.${orderBy}


    order by t.create_time desc



    limit #{page}, #{row}

mapper.update:
update fee_receipt_detail t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.area= #{area}


    , t.amount= #{amount}


    , t.fee_name= #{feeName}


    , t.start_time= #{startTime}


    , t.end_time= #{endTime}


    , t.fee_id= #{feeId}


    , t.cycle= #{cycle}


    , t.print_count= #{printCount}

where 1=1

    and t.receipt_id= #{receiptId}


    and t.community_id= #{communityId}


    and t.detail_id= #{detailId}

